"use strict";(globalThis.webpackChunkmy_website||=[]).push([[80410],{12297(e){e.exports=JSON.parse('{"slug":"stablecoin","title":"Stablecoin","short":"A cryptocurrency designed to track the value of a reference asset, typically a fiat currency like the US dollar, so balances stay predictable rather than swinging with the crypto market.","category":"tokens","aliases":[],"mentalModel":"A digital IOU pegged to a real-world currency. Some stablecoins hold actual dollars in a bank to back the peg (fiat-backed), others lock up crypto as collateral and use code to hold the price in line (crypto-backed). The peg only holds as long as the backing mechanism does.","related":["djed","usdm","programmable-token"],"sources":[],"link":"/stablecoins","level":"beginner","body":"On Cardano, USDM is a fiat-backed stablecoin while Djed is crypto-backed, holding an overcollateralized ada reserve; together with synthetic designs like iUSD they show the main families of stablecoin in use."}')}}]);